import { normalizeWords } from './helper';

type PluginContext = import('../../kernel/types').PluginContext;

export default {
  id: 'words',
  name: 'Words',
  version: '1.0.0',
  onLoad(ctx: PluginContext) {
    ctx.register({
      kind: 'tool',
      tool: {
        name: 'normalize_words',
        version: '1.0.0',
        description: 'Split text on whitespace, lowercase words, deduplicate them and sort ascending. Returns the sorted word list and a comma-joined string.',
        permissions: [],
        sideEffect: 'none',
        parameters: {
          type: 'object',
          properties: {
            text: { type: 'string', description: 'Input text containing whitespace-separated words.' }
          },
          required: ['text']
        },
        outputSchema: {
          type: 'object',
          properties: {
            words: { type: 'array', items: { type: 'string' } },
            text: { type: 'string', description: 'Comma-joined sorted unique words.' }
          },
          required: ['words', 'text']
        },
        async handler(args: unknown, _tctx: unknown) {
          const { text } = args as { text: string };
          const words = normalizeWords(text);
          return { ok: true as const, data: { words, text: words.join(',') } };
        }
      }
    });
  }
};

files.helper.ts:
/** Pure helpers for word normalization. No I/O, no host APIs. */

/** Split text into lowercase, unique, ascending-sorted words. */
export function normalizeWords(text: string): string[] {
  const unique = new Set<string>();
  for (const raw of String(text).split(/\s+/)) {
    const word = raw.toLowerCase();
    if (word.length > 0) unique.add(word);
  }
  return Array.from(unique).sort();
}

/** Join a word list with commas, keeping sort order. */
export function joinWords(words: string[]): string {
  return words.join(',');
}

